		bitsObj = longAt((void *)((cursorObj + BaseHeaderSize) + (0U << (shiftForWord()))));
		extentX = fetchIntegerofObject(1, cursorObj);
		extentY = fetchIntegerofObject(2, cursorObj);
		depth = fetchIntegerofObject(3, cursorObj);
		offsetObj = longAt((void *)((cursorObj + BaseHeaderSize) + (4U << (shiftForWord()))));
		successBoolean = (/* isPointers: */
				((!(offsetObj & (tagMask()))))
			 && (((byteAt((void *)(offsetObj + (formatFieldByteOffset())))) & (formatMask())) <= 5 /* lastPointerFormat */))
			 && ((lengthOf(offsetObj)) >= 2);

		/* begin success: */
		if (!successBoolean) {
			if (!GIV(primFailCode)) {
				GIV(primFailCode) = 1;
			}
		}
