				 && (extentY > 0);

			/* begin success: */
			if (!successBoolean) {
				if (!GIV(primFailCode)) {
					GIV(primFailCode) = 1;
				}
			}
			successBoolean = (offsetX >= (extentX * -1))
				 && (offsetX <= 0);

