			if (!successBoolean) {
				if (!GIV(primFailCode)) {
					GIV(primFailCode) = 1;
				}
			}
			successBoolean = (offsetY >= (extentY * -1))
				 && (offsetY <= 0);

			/* begin success: */
			if (!successBoolean) {
				if (!GIV(primFailCode)) {
					GIV(primFailCode) = 1;
				}
			}
			successBoolean = (/* isWords: */
					((!(bitsObj & (tagMask()))))
				 && (((((byteAt((void *)(bitsObj + (formatFieldByteOffset())))) & (formatMask())) >= (firstLongFormat())) && (((byteAt((void *)(bitsObj + (formatFieldByteOffset())))) & (formatMask())) <= ((firstShortFormat()) - 1)))))
				 && ((lengthOf(bitsObj)) == (extentX * extentY));

