	/* begin pop:thenPush: */
	longAtput((sp = GIV(stackPointer) + (((GIV(argumentCount) + 1) - 1) * BytesPerWord)),GIV(falseObj));
	GIV(stackPointer) = sp;
	addLastLinktoList(activeProc, criticalSection);

