					if (nextFreeChunk) {
						/* begin storePointer:ofFreeChunk:withValue: */
						assert(isFreeObject(nextFreeChunk));
						assert((prev == 0)
						 || (isFreeObject(prev)));
						longAtput((void *)((nextFreeChunk + BaseHeaderSize) + (1U << (shiftForWord()))),prev);
					}
