						assert((classIndexOf(objSqInt)) > (isForwardedObjectClassIndexPun()));
						i = (((numSlots = byteAt((void *)(objSqInt + (numSlotsFieldByteOffset()))))) == (numSlotsMask())
									? ((((usqInt)(((sqInt)((usqInt)((longAt((void *)(objSqInt - BaseHeaderSize)))) << 8)))))) >> 8
									: numSlots);
