			while (/* isOopForwarded: */
				((!(referent & (tagMask()))))
			 && ((!((longAt((void *)(referent))) & ((classIndexMask()) - (isForwardedObjectClassIndexPun())))))) {
				referent = longAt((void *)((referent + BaseHeaderSize) + (0U << (shiftForWord()))));
			}
