	if ((GIV(tempOop) != 0)
	 && (/* shouldRemapOop: */
		((!(GIV(tempOop) & (tagMask()))))
	 && (shouldRemapObj(GIV(tempOop))))) {
		GIV(tempOop) = remapObj(GIV(tempOop));
	}
	if ((GIV(tempOop2) != 0)
	 && (/* shouldRemapOop: */
		((!(GIV(tempOop2) & (tagMask()))))
	 && (shouldRemapObj(GIV(tempOop2))))) {
		GIV(tempOop2) = remapObj(GIV(tempOop2));
	}
